const body = $input.first().json.body || $input.first().json;
const leads = body.leads || [];

if (!leads.length) throw new Error('No leads in payload');

const total = leads.length;
const emails = leads.map(l => (l.email || '').toLowerCase()).filter(Boolean);
const dupes = emails.length - new Set(emails).size;
const dupePct = (dupes / total) * 100;

const catchAll = ['info','contact','hello','sales','admin','team'];
const catchAlls = emails.filter(e => catchAll.includes(e.split('@')[0])).length;
const catchPct = (catchAlls / total) * 100;

const badPatterns = /intern|assistant|coordinator|student|retired/i;
const badTitles = leads.filter(l => badPatterns.test(l.job_title || l.title || '')).length;
const badPct = (badTitles / total) * 100;

const verified = leads.filter(l => ['ok','verified','valid'].includes((l.email_status || l.verification_status || '').toLowerCase())).length;
const hasVerCol = leads.some(l => l.email_status || l.verification_status);
const verScore = hasVerCol ? Math.round((verified / total) * 100) : 0;

const fakeNames = leads.filter(l => !l.first_name || !l.last_name || l.first_name.toLowerCase() === 'admin').length;
const nameScore = Math.round(((total - fakeNames) / total) * 100);

const dupeScore = Math.max(0, Math.round(100 - dupePct * 20));
const catchScore = catchPct < 5 ? 100 : (catchPct < 15 ? 50 : 0);
const badScore = Math.max(0, Math.round(100 - badPct * 10));

const overall = Math.round((verScore * 2 + dupeScore + catchScore + badScore + nameScore) / 6);
const grade = overall >= 90 ? 'A' : overall >= 80 ? 'B' : overall >= 70 ? 'C' : overall >= 60 ? 'D' : 'F';
const pass = overall >= 80;

const issues = [];
if (!hasVerCol) issues.push('No verification column');
if (dupes > 0) issues.push(`${dupes} duplicate emails`);
if (catchAlls > 0) issues.push(`${catchAlls} catch-all addresses`);
if (badTitles > 0) issues.push(`${badTitles} bad titles`);
if (fakeNames > 0) issues.push(`${fakeNames} fake/missing names`);

return [{
  json: {
    total, grade, overall, pass,
    dimensions: { verification: verScore, duplicates: dupeScore, catch_all: catchScore, bad_titles: badScore, names: nameScore },
    issues,
    leads: pass ? leads : []
  }
}];

